from PIL import Image, ImageDraw
import numpy as np
im = Image.open('radiograph.jpg').convert('L')
a = np.asarray(im).astype(np.float32)/255.0
g = np.clip((a**1.6)*255, 0, 255).astype(np.uint8)
en = Image.fromarray(g)
def crop(name, box, f=4.0):
    x1,y1,x2,y2 = box
    c = en.crop(box)
    d = ImageDraw.Draw(c)
    for gx in range(x1 - x1%50, x2, 50):
        if gx>x1:
            col = 200 if gx%100==0 else 120
            d.line([(gx-x1,0),(gx-x1,c.height)], fill=col, width=1)
            if gx%100==0: d.text((gx-x1+2,2), str(gx), fill=255)
    for gy in range(y1 - y1%50, y2, 50):
        if gy>y1:
            col = 200 if gy%100==0 else 120
            d.line([(0,gy-y1),(c.width,gy-y1)], fill=col, width=1)
            if gy%100==0: d.text((2,gy-y1+2), str(gy), fill=255)
    c = c.resize((int(c.width*f), int(c.height*f)), Image.LANCZOS)
    c.save(f'/tmp/z2_{name}.png')
crop('ur_m1_apex', (640, 380, 820, 560))
print('ok')
